// (Caution) INTENTIONALLY BROKEN — demonstrates file handle leak
package com.bank.csvrecon.service;

import com.bank.csvrecon.dto.FileReconResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Stream;

@Service
@Slf4j
public class LeakyFileService {

    public FileReconResult readLeaky() throws IOException {
        Path csvPath = new ClassPathResource("sample-trades.csv").getFile().toPath();

        // (Caution) LEAK: Stream from Files.lines() — file handle opened but NEVER closed!
        Stream<String> lines = Files.lines(csvPath);

        List<String> settled = lines
            .skip(1)  // skip header
            .filter(line -> line.contains("SETTLED"))
            .map(line -> line.split(",")[0])  // extract trade ID
            .toList();
        // File handle is still OPEN here!
        // If this method is called 1000 times: 1000 open file handles → crash!

        log.warn("(Caution) LEAK: File handle for {} was NOT closed! " +
            "Under load: 'Too many open files'", csvPath.getFileName());

        return new FileReconResult("LEAKY (no close)", -1, settled.size(), settled,
            "FILE HANDLE LEAKED — not closed after terminal operation!",
            "Stream from Files.lines() holds BufferedReader + FileInputStream. " +
            "Without close(), OS file handles accumulate until ulimit hit.");
    }
}
