// ─── File: src/main/java/com/bank/csvrecon/service/SafeFileService.java ───
// (Recommended) FIXED — try-with-resources ensures file handle is closed
package com.bank.csvrecon.service;

import com.bank.csvrecon.dto.FileReconResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Stream;

@Service
@Slf4j
public class SafeFileService {

    // ═══ FIX: try-with-resources — file handle closed automatically ═══
    public FileReconResult readSafe() throws IOException {
        Path csvPath = new ClassPathResource("sample-trades.csv").getFile().toPath();

        List<String> settled;

        // try-with-resources: Stream is AutoCloseable
        try (Stream<String> lines = Files.lines(csvPath)) {
            settled = lines
                .skip(1)  // skip CSV header
                .filter(line -> line.contains("SETTLED"))
                .map(line -> line.split(",")[0])
                .toList();
        }  // ← file handle CLOSED here, even if exception thrown!

        log.info("(Recommended) SAFE: File handle closed for {}", csvPath.getFileName());

        return new FileReconResult("SAFE (try-with-resources)",
            -1, settled.size(), settled,
            "FILE HANDLE CLOSED — try-with-resources called stream.close()",
            "Stream.close() releases BufferedReader + FileInputStream. " +
            "AutoCloseable ensures cleanup even on exception.");
    }

    // ═══ onClose callback — observe when stream closes ═══
    public FileReconResult readWithOnClose() throws IOException {
        Path csvPath = new ClassPathResource("sample-trades.csv").getFile().toPath();

        List<String> settled;

        try (Stream<String> lines = Files.lines(csvPath)
                .onClose(() -> log.info(" onClose callback: file handle released!"))) {
            settled = lines
                .skip(1)
                .filter(line -> line.contains("SETTLED"))
                .map(line -> line.split(",")[0])
                .toList();
        }  // onClose callback fires HERE

        return new FileReconResult("SAFE + onClose",
            -1, settled.size(), settled,
            "FILE HANDLE CLOSED — onClose callback confirmed",
            "Stream.onClose(Runnable) registers cleanup. Fires on stream.close().");
    }

    // ═══ Collection.stream() — NO close needed ═══
    public FileReconResult readFromCollection() {
        List<String> inMemory = List.of(
            "TRD-001,RELIANCE,BUY,100,2450.50,SETTLED",
            "TRD-002,TCS,BUY,50,3520.00,SETTLED",
            "TRD-003,HDFC,SELL,200,1650.75,PENDING");

        // NO try-with-resources needed — in-memory, no OS resource
        List<String> settled = inMemory.stream()
            .filter(line -> line.contains("SETTLED"))
            .map(line -> line.split(",")[0])
            .toList();
        // Stream is consumed and garbage collected — no handle to close

        return new FileReconResult("COLLECTION (no close needed)",
            inMemory.size(), settled.size(), settled,
            "NO RESOURCE — in-memory list, GC handles cleanup",
            "Collection.stream() reads from RAM. No file handle, no OS resource.");
    }
}
