package com.bank.csvrecon.controller;

import com.bank.csvrecon.dto.FileReconResult;
import com.bank.csvrecon.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/csv-recon")
@RequiredArgsConstructor
public class ReconController {

    private final LeakyFileService leakyService;
    private final SafeFileService safeService;

    @GetMapping("/leaky")
    public FileReconResult leaky() throws Exception { return leakyService.readLeaky(); }

    @GetMapping("/safe")
    public FileReconResult safe() throws Exception { return safeService.readSafe(); }

    @GetMapping("/onclose")
    public FileReconResult onClose() throws Exception { return safeService.readWithOnClose(); }

    @GetMapping("/collection")
    public FileReconResult collection() { return safeService.readFromCollection(); }
}
