// ─── File: src/test/java/com/bank/csvrecon/service/ResourceStreamTest.java ───
package com.bank.csvrecon.service;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.IOException;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class ResourceStreamTest {

    @TempDir Path tempDir;

    @Test
    void filesLinesMustBeClosed() throws IOException {
        Path file = tempDir.resolve("trades.csv");
        Files.writeString(file, "TRD-001,SETTLED\nTRD-002,PENDING\nTRD-003,SETTLED");

        // SAFE: try-with-resources
        List<String> settled;
        try (Stream<String> lines = Files.lines(file)) {
            settled = lines.filter(l -> l.contains("SETTLED")).toList();
        }
        assertThat(settled).hasSize(2);
    }

    @Test
    void onCloseCallbackFires() throws IOException {
        Path file = tempDir.resolve("test.csv");
        Files.writeString(file, "A\nB\nC");

        AtomicBoolean closed = new AtomicBoolean(false);

        try (Stream<String> lines = Files.lines(file)
                .onClose(() -> closed.set(true))) {
            lines.count();
        }
        assertThat(closed.get()).isTrue();  // onClose callback fired!
    }

    @Test
    void collectionStreamDoesNotNeedClosing() {
        // No try-with-resources needed — in-memory
        long count = List.of("A", "B", "C").stream().count();
        assertThat(count).isEqualTo(3);
        // Stream is simply garbage collected — no resource leak
    }

    @Test
    void filesWalkMustBeClosed() throws IOException {
        Path subDir = tempDir.resolve("reports");
        Files.createDirectories(subDir);
        Files.writeString(subDir.resolve("jan.txt"), "data");
        Files.writeString(subDir.resolve("feb.txt"), "data");

        List<Path> files;
        try (Stream<Path> walk = Files.walk(tempDir)) {
            files = walk.filter(p -> p.toString().endsWith(".txt")).toList();
        }
        assertThat(files).hasSize(2);
    }

    @Test
    void filesListMustBeClosed() throws IOException {
        Files.writeString(tempDir.resolve("a.csv"), "data");
        Files.writeString(tempDir.resolve("b.csv"), "data");

        List<Path> csvFiles;
        try (Stream<Path> list = Files.list(tempDir)) {
            csvFiles = list.filter(p -> p.toString().endsWith(".csv")).toList();
        }
        assertThat(csvFiles).hasSize(2);
    }
}
